    ('20148', 3, $$Cat and Dog play with the ball.$$),
    ('20148', 4, $$Then Cat throws the ball very high.$$),
    ('20148', 5, $$The ball is on the roof.$$),
    ('20148', 6, $$Cat and Dog can see the ball.$$),
