    ('20148', 12, $$$$),
    ('20150', 0, $$This is Cat.$$),
    ('20150', 1, $$Cat and Dog walk.$$),
    ('20150', 2, $$Then they see an egg.$$),
    ('20150', 3, $$Cat and Dog walk to a bird.$$),
    ('20150', 4, $$But the bird says,$$),
    ('20150', 5, $$Cat and Dog walk to the owl.$$),
    ('20150', 6, $$But the owl says,$$),
    ('20150', 7, $$Cat and Dog walk to the goose.$$),
    ('20150', 8, $$But the goose says, "No, that is not my egg.$$),
    ('20150', 9, $$Cat and Dog walk to the two ducks.$$),
    ('20150', 10, $$But the two ducks say, "No, that is not our egg. "$$),
    ('20150', 11, $$There is a lizard in the egg.$$),
    ('20150', 12, $$The baby lizard says,$$),
