    ('20870', 2, $$Lioness’s cubs did not have enough food to eat.$$),
    ('20870', 3, $$Lioness wished the fat chicks were hers.$$),
    ('20870', 4, $$When Ostrich was not home, Lioness took the chicks.$$),
    ('20870', 5, $$When Ostrich returned, she asked, “Where are my children? ”$$),
    ('20870', 6, $$Ostrich found her chicks with Lioness at her hut.$$),
    ('20870', 7, $$Lioness said, “The chicks are mine now. Take the cubs. ”$$),
    ('20870', 8, $$Ostrich asked herself, “How can I get my children back? ”$$),
    ('20870', 9, $$She called all the animals for a meeting.$$),
    ('20870', 10, $$The animals arrived for the meeting.$$),
    ('20870', 11, $$Elephant asked Ostrich and Lioness to speak.$$),
