    ('20870', 14, $$Then Squirrel ran into a hole.$$),
    ('20870', 15, $$Lioness was very angry. She went home with her cubs.$$),
    ('20873', 0, $$There was a young beautiful mule called Wardit.$$),
    ('20873', 1, $$A handsome horse said, “I must marry Wardit. ”$$),
    ('20873', 2, $$The horse said, “Let us go together to the river. ”$$),
    ('20873', 3, $$The horse asked Wardit to be his wife. Wardit agreed.$$),
    ('20873', 4, $$The horse asked Wardit, “Who are your father and mother? ”$$),
    ('20873', 5, $$Wardit said, “My mother lives in the king’s palace. ”$$),
    ('20873', 6, $$“My sister lives in the Church compound. Don’t you know her? ”$$),
    ('20873', 7, $$She added, “My beautiful aunt lives with the village headman. ”$$),
    ('20873', 8, $$Then an old donkey walked by. It was Wardit’s father.$$),
    ('20873', 9, $$Wardit did not greet her father or look at him.$$),
