    ('20884', 0, $$Long ago, animals had no legs.$$),
    ('20884', 1, $$Maguru had given legs only to people.$$),
    ('20884', 2, $$Maguru decided to give legs to every animal.$$),
    ('20884', 3, $$The animals wanted legs to walk and run.$$),
    ('20884', 4, $$It was hard for them to crawl.$$),
    ('20884', 5, $$When the day came, different animals crawled to Maguru's house.$$),
    ('20884', 6, $$Maguru gave legs to animals and birds.$$),
    ('20884', 7, $$Some animals danced, while others fell down.$$),
    ('20884', 8, $$They said, "We will never crawl again. "$$),
    ('20884', 9, $$Millipede was the last animal on the line.$$),
    ('20884', 10, $$Maguru gave Millipede all the remaining legs.$$),
    ('20884', 11, $$Millipede said happily, “I will move faster than others. ”$$),
    ('20884', 12, $$After Millipede, Snake came begging, “Please give me some legs. ”$$),
    ('20884', 13, $$Snake said to Maguru, “I over-slept.$$),
    ('20884', 14, $$Maguru did not find any legs for Snake.$$),
    ('20884', 15, $$From that day, Snake still waits to get legs.$$),
    ('20886', 0, $$There was a drought. Mulongo’s family had no food.$$),
    ('20886', 1, $$One day, Mulongo led them into the forest for food.$$),
    ('20886', 2, $$They found a banana plantation but there was no owner.$$),
    ('20886', 3, $$Suddenly, a big ogre arrived!$$),
    ('20886', 4, $$Then one morning he said, “Cook your son for me. ”$$),
    ('20886', 5, $$In the evening, the ogre said, “Cook your daughter tomorrow. ”$$),
    ('20886', 6, $$The parents hid their daughter in a tree.$$),
    ('20886', 7, $$The ogre said, “Tomorrow you must cook your husband.$$),
    ('20886', 8, $$That evening, the ogre asked the wife to cook herself!$$),
    ('20886', 9, $$After eating, the ogre lay under the tree snoring.$$),
    ('20886', 10, $$The ogre saw all of them alive.$$),
    ('20886', 11, $$They tricked the ogre and came down from the tree.$$),
    ('20892', 0, $$My friend Kiki and I walk home from school.$$),
    ('20892', 1, $$One day, a man followed us.$$),
    ('20892', 2, $$His teeth were brown. He had pimples on the face.$$),
    ('20892', 3, $$When we looked at him, he shouted at us angrily.$$),
    ('20892', 4, $$They threw me into a van.$$),
    ('20892', 5, $$Kiki managed to ran away.$$),
    ('20892', 6, $$They put me in a dark room. My hands were tied.$$),
    ('20892', 7, $$A man said, “Eat this food. The journey is long. ”$$),
    ('20892', 8, $$As I ate, the man smoked a cigarette.$$),
    ('20892', 9, $$Suddenly, the other men came in pulling my friend Kiki.$$),
    ('20892', 10, $$We heard the men arguing and shouting in the next room.$$),
    ('20892', 11, $$Kiki said, “We must escape. Our parents cannot pay them. ”$$),
    ('20892', 12, $$We pulled the timber from the window until we saw light.$$),
    ('20892', 13, $$Kiki climbed out and ran to get help.$$),
    ('20892', 14, $$The men rushed into the room. The leader was angry.$$),
    ('20892', 15, $$They went back to the other room and continued arguing.$$),
    ('20892', 16, $$I heard a voice saying, “Don’t be afraid. Police are here. ”$$),
    ('20892', 17, $$They were shouting and making noise. I heard some gunshots.$$),
    ('20892', 18, $$A policewoman said, “Everything is over. You are safe now. ”$$),
    ('20892', 19, $$After that day, Kiki and I were more careful.$$),
    ('20910', 0, $$Mother and father left their baby with their older children.$$),
    ('20910', 1, $$The older children played and forgot about the baby.$$),
    ('20910', 2, $$One day, cranes came across the crying baby.$$),
    ('20910', 3, $$They lifted the baby in its blanket and flew away.$$),
    ('20910', 4, $$The mother saw four cranes flying away with her baby.$$),
    ('20910', 5, $$The cranes looked after the baby.$$),
    ('20910', 6, $$While the cranes were away, a frog swallowed the baby!$$),
    ('20910', 7, $$For three flies, the frog returned the baby to its parents.$$),
    ('20911', 0, $$One day, Dog found eggs at the river$$),
    ('20911', 1, $$Dog put the ten eggs in his bag.$$),
    ('20911', 2, $$Dog looked after the eggs and kept them warm.$$),
    ('20911', 3, $$Crocodile asked Dog, “Have you seen my eggs? ”$$),
    ('20911', 4, $$Crocodile asked all animals about her eggs.$$),
    ('20911', 5, $$Meanwhile, the eggs hatched one by one.$$),
    ('20911', 6, $$Dog could not give the young crocodiles enough food.$$),
    ('20911', 7, $$One day, Crocodile heard the rumbling bellies of young crocodiles!$$),
    ('20911', 8, $$Crocodile went inside and hit Dog with her tail.$$),
    ('20911', 9, $$Crocodile chased Dog down the road.$$),
    ('20911', 10, $$Dog stopped and said to Crocodile, "I am sorry! "$$),
    ('20911', 11, $$Crocodile forgave him and went to swim with her children.$$),
    ('20917', 0, $$Hare met Elephant carrying a pot of honey.$$),
    ('20917', 1, $$Elephant carried Hare on his back. Hare ate Elephant’s honey.$$),
    ('20917', 2, $$They found a big buffalo drinking water in a river.$$),
    ('20917', 3, $$Hare wanted to know who was stronger, Buffalo or Elephant.$$),
    ('20917', 4, $$Hare said he had an idea how to find out.$$),
    ('20917', 5, $$Hare tied one end of a rope around Elephant’s waist.$$),
    ('20917', 6, $$Hare tied the other end around Buffalo’s waist.$$),
    ('20917', 7, $$Hare hid in a tree and shouted, “Pull! ”$$),
    ('20917', 8, $$Buffalo and Elephant pulled. Elephant pulled Buffalo.$$),
    ('20917', 9, $$Buffalo pulled Elephant. Neither could win.$$),
    ('20917', 10, $$Hare cut the rope, closer to Buffalo.$$),
    ('20917', 11, $$Hare praised Buffalo saying, “You are stronger. ”$$),
    ('20936', 0, $$Long time ago an elephant and a spirit were in contest. They wanted to know who was mightiest between them.$$),
    ('20936', 1, $$Each of them believed he was stronger than the other.$$),
    ('20936', 2, $$It rained heavily that evening. The weather became extremely cold.$$),
    ('20936', 3, $$The elephant was asked to stop the rain. The elephant trumpeted, "Auuu Rrrrruuuuu! "$$),
    ('20936', 4, $$Instead of stopping the rain, the spirit caused loud thunder, which crashed continuously.$$),
    ('20936', 5, $$Then the spirit asked the elephant, "Do you still doubt my power? "$$),
    ('20936', 6, $$The elephant said, "I am the greatest among all creatures on earth. I thought I would be greater than you. "$$),
    ('20936', 7, $$Since that contest, the elephant feared the spirit.$$),
    ('2102', 0, $$Long ago, there was no night in Opio's village. People slept when they were tired and worked when they were awake.$$),
    ('2102', 1, $$One day Opio went out hunting with his dogs. After a short time, his dogs started to chase an antelope. Opio followed them. He ran for many hours. Every time he became tired, he rested. Then he would run again. But he could not find his dogs.$$),
    ('2102', 2, $$After many days, he came to a village. He went to one of the houses and said to the owner, "I have chased an antelope for a long time and I am very tired. I want to rest. " The man said, "Sit down and rest. Would you like some beer? " Opio was very thirsty so he drank some. Then he went to sleep.$$),
    ('2102', 3, $$When he woke up, he couldn't see. He opened and closed his eyes many times. "You have given me something very bad to drink," he said to the man. "I can't see properly anymore! " "There is nothing wrong with you," the man replied. "It's night now. Haven't you ever seen night? When the day leaves, the night comes. "$$),
    ('2102', 4, $$Opio asked many questions about the night. He began to like it very much. He and his new friend talked until morning. He stayed for another day so that he could see the night come again.$$),
    ('2102', 5, $$The next morning he asked his friend, "How can I take the night to my own village? I want my people to see the night. " The man explained, "When it starts to get dark this evening, walk to your village. If you look straight in front, the night will follow you. If you look back, the night will go away. "$$),
    ('2102', 6, $$Opio did as he was told. That evening, he began to walk towards his village. He felt the dark night behind him as he walked. He was tempted to look back, but he did not.$$),
    ('2102', 7, $$When he came to his village, the villagers were afraid. They asked Opio, "What disease have you brought to us? What is this dark thing following you? " Opio said, "My friends, this dark thing is called night. You are afraid and I was afraid, too. "$$),
    ('2102', 8, $$Opio continued to explain, "You will learn to like the night. When the light comes we can work and when night comes, we can rest. "$$),
    ('2102', 9, $$And that is how night came to Opio's village.$$),
    ('2104', 0, $$Once upon a time, there was a hungry jackal. He was walking around the bush looking for food.$$),
    ('2104', 1, $$He came across a grapevine. He spotted a bunch of juicy ripe grapes hanging from a high branch.$$),
    ('2104', 2, $$"Those look really delicious," he thought. He took a few steps back so that he could make his highest jump.$$),
    ('2104', 3, $$The grapes were too high. Jackal fell on his back without even touching the bunch.$$),
    ('2104', 4, $$Jackal got up and went further back from his starting spot. He ran, and almost got high enough. But he fell even harder.$$),
    ('2104', 5, $$He tried again and again. But he couldn't get to the grapes. He kept falling until his back was very sore.$$),
    ('2104', 6, $$Finally, he gave up and walked away.$$),
    ('2104', 7, $$He stopped and looked back at the grapes. He was hungrier than ever. "Those grapes look really sour anyway," he thought.$$),
    ('2124', 0, $$Once there was a family who had a tree with such sweet fruit that everyone visited their compound to taste the fruit. The family also had a very beautiful daughter. Many people admired her dazzling beauty, white eyes and above all, her great personality.$$),
    ('2124', 1, $$When she grew up into a young woman, young and old men flocked to her home seeking her hand in marriage. Her parents decided that the man who could sit in the compound the whole day without eating any fruit would be given her hand in marriage.$$),
    ('2124', 2, $$The news spread all over the village. The first man to come was the head of all farmers in the village. He was handsome, rich and young. He was welcomed and served the fruit. He sat for a few minutes, but before long, he ate the fruit and was sent away.$$),
    ('2124', 3, $$The leader of animal keepers was next. He was handsome, young and rich. The girl admired him. But when he was served with the fruit, he immediately ate it, and was sent away.$$),
    ('2124', 4, $$The next man to come had many pieces of land. He was arrogant and ugly. The girl prayed that he would eat and go away. When served, he refused to eat. The time passed, and the girl started begging him to eat. By around four o'clock, he was overcome with hunger, and he ate. He, too, was sent away.$$),
    ('2124', 5, $$Next, the chief came around. He was arrogant, old, and ugly. No one liked him in the village. The girl wished that he would eat and go away. When he was served with the fruit, he refused to eat. He stayed the whole day. At about six o'clock, he asked if he could go to the toilet.$$),
    ('2124', 6, $$He was allowed to go. When he returned, the aroma of the fruit hung around him, and his lips were red! He had eaten the fruit in the toilet! To the girl's relief, he was sent away.$$),
    ('2124', 7, $$A few days later, a young, handsome, rich prince arrived. The girl looked at him in admiration. She took him aside, and begged him not to eat the fruit. She served him much less fruit than the other suitors. But by midday the prince had already eaten and was sent away. The girl burst into tears of anger and disappointment.$$),
    ('2124', 8, $$The next day, a farmer came around. He was poor and lazy, but he was young and popular among many people for being a great talker. He came determined to win. The girl served him many fruits and asked him to eat and go away.$$),
    ('2124', 9, $$When he was served, he refused to eat. The girl waited painfully. Midday passed, and then two o'clock. At four o'clock, the farmer asked for water. The girl prayed that he would eat the fruit, but she was still praying when the clock turned to seven. This farmer had overcome the test of endurance set by the parents!$$),
    ('2124', 10, $$Her parents had to hand over their daughter to the "lazy one. " The girl begged to be saved from her fate, but her parents could do nothing. As the farmer took her home, he sang such a beautiful song while clapping his hands. Many people flocked to the road to see the couple.$$),
    ('2124', 11, $$Among the people were servants of the rich prince. They called the farmer aside, and offered him money and cattle if he would leave the girl. Without a moment's hesitation, he took the money and the cattle, and walked off.$$),
    ('2124', 12, $$The servants dressed the girl in fine clothes and took her to the palace, straight to the prince. Before long, her parents were called and a ceremony was organised to join the two in marriage.$$)
  ) AS v(source_id, page_index, text)
  JOIN books b
    ON b.source_platform = 'african_storybook' AND b.source_id = v.source_id
ON CONFLICT (book_id, page_index) DO NOTHING;

-- ───────── [적재검증] 트랜잭션 안 ─────────
-- (c) 적재 후 행 수 — 기대 582
SELECT count(*) AS rows_after FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('19100', '19194', '19260', '1938', '19414', '19421', '19467', '19470', '19474', '19752', '19761', '19762', '19766', '19767', '19830', '19854', '19885', '19898', '19933', '19986', '20147', '20148', '20150', '20158', '20205', '20299', '20302', '20367', '20550', '20587', '20814', '2084', '20853', '20870', '20873', '20874', '20876', '20879', '20884', '20886', '20892', '20910', '20911', '20917', '20936', '2102', '2104', '2124');
-- (d) 조인 실패로 누락된 source_id — 기대 0행
SELECT v.source_id FROM (VALUES ('19100'), ('19194'), ('19260'), ('1938'), ('19414'), ('19421'), ('19467'), ('19470'), ('19474'), ('19752'), ('19761'), ('19762'), ('19766'), ('19767'), ('19830'), ('19854'), ('19885'), ('19898'), ('19933'), ('19986'), ('20147'), ('20148'), ('20150'), ('20158'), ('20205'), ('20299'), ('20302'), ('20367'), ('20550'), ('20587'), ('20814'), ('2084'), ('20853'), ('20870'), ('20873'), ('20874'), ('20876'), ('20879'), ('20884'), ('20886'), ('20892'), ('20910'), ('20911'), ('20917'), ('20936'), ('2102'), ('2104'), ('2124')) AS v(source_id)
  WHERE NOT EXISTS (SELECT 1 FROM books b
     WHERE b.source_platform='african_storybook' AND b.source_id=v.source_id);
-- (e) source 라벨 분포 — 기대 manifest_txt_v1 1종 / 582행
SELECT bt.source, count(*) FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('19100', '19194', '19260', '1938', '19414', '19421', '19467', '19470', '19474', '19752', '19761', '19762', '19766', '19767', '19830', '19854', '19885', '19898', '19933', '19986', '20147', '20148', '20150', '20158', '20205', '20299', '20302', '20367', '20550', '20587', '20814', '2084', '20853', '20870', '20873', '20874', '20876', '20879', '20884', '20886', '20892', '20910', '20911', '20917', '20936', '2102', '2104', '2124')
  GROUP BY bt.source;
-- (f) page_index 축 검증 — 권마다 0부터 연속이어야 한다. 기대 0행(위반 없음)
SELECT b.source_id, min(bt.page_index) AS mn, max(bt.page_index) AS mx, count(*) AS n
  FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('19100', '19194', '19260', '1938', '19414', '19421', '19467', '19470', '19474', '19752', '19761', '19762', '19766', '19767', '19830', '19854', '19885', '19898', '19933', '19986', '20147', '20148', '20150', '20158', '20205', '20299', '20302', '20367', '20550', '20587', '20814', '2084', '20853', '20870', '20873', '20874', '20876', '20879', '20884', '20886', '20892', '20910', '20911', '20917', '20936', '2102', '2104', '2124')
  GROUP BY b.source_id HAVING min(bt.page_index) <> 0 OR max(bt.page_index) <> count(*)-1;
-- (g) 빈 면 행 수 — 기대 1 (D7: 빈 면도 text='' 로 적재)
SELECT count(*) AS empty_rows FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('19100', '19194', '19260', '1938', '19414', '19421', '19467', '19470', '19474', '19752', '19761', '19762', '19766', '19767', '19830', '19854', '19885', '19898', '19933', '19986', '20147', '20148', '20150', '20158', '20205', '20299', '20302', '20367', '20550', '20587', '20814', '2084', '20853', '20870', '20873', '20874', '20876', '20879', '20884', '20886', '20892', '20910', '20911', '20917', '20936', '2102', '2104', '2124') AND bt.text = '';

-- ───────── [종료] ─────────
-- (c)~(g)가 전부 기대값과 일치하면 아래 ROLLBACK; 을 COMMIT; 으로 바꿔 타이핑한다.
ROLLBACK;
